import React, { useState } from 'react';

const ITEMS = [
  {
    action: 'Display a button the user can click',
    answer: 'Client',
    why: 'The browser is responsible for displaying and interacting with the interface.'
  },
  {
    action: 'Store a user\'s profile data',
    answer: 'Server',
    why: 'Persistent application data is commonly stored and managed by backend systems.'
  },
  {
    action: 'Send a request for product data',
    answer: 'Client',
    why: 'The browser can initiate a request asking a server for data.'
  }
];

export default function ClientServerDemo() {
  const [index, setIndex] = useState(0);
  const item = ITEMS[index];
  const [revealed, setRevealed] = useState(false);

  return (
    <div style={{ padding: 16, background: '#0d1117', color: '#e6edf3', fontFamily: 'sans-serif' }}>
      <p style={{ color: '#8b949e', marginTop: 0 }}>Classify this action:</p>
      <div style={{ padding: 16, border: '1px solid #30363d', borderRadius: 8, marginBottom: 12 }}>
        <strong>{item.action}</strong>
      </div>
      {revealed && (
        <div style={{ padding: 12, background: '#161b22', borderRadius: 8, marginBottom: 12 }}>
          <p style={{ margin: '0 0 6px' }}>Answer: <strong>{item.answer}</strong></p>
          <p style={{ margin: 0, color: '#8b949e' }}>{item.why}</p>
        </div>
      )}
      <div style={{ display: 'flex', gap: 8 }}>
        <button onClick={() => setRevealed(true)}>Reveal</button>
        <button onClick={() => { setIndex((i) => (i + 1) % ITEMS.length); setRevealed(false); }}>
          Next
        </button>
      </div>
    </div>
  );
}

import React, { useState } from 'react';

const STAGES = [
  {
    name: 'URL',
    detail: 'The browser identifies the destination, such as https://example.com/products.'
  },
  {
    name: 'DNS',
    detail: 'The hostname may be resolved to an IP address if a suitable answer is not already cached.'
  },
  {
    name: 'Connection',
    detail: 'The browser establishes the network communication it needs. HTTPS also includes security negotiation.'
  },
  {
    name: 'Request',
    detail: 'The browser sends an HTTP request such as GET /products.'
  },
  {
    name: 'Response',
    detail: 'The server sends back an HTTP response with a status and content or other information.'
  },
  {
    name: 'Render',
    detail: 'The browser processes HTML and related resources and begins building and painting the page.'
  }
];

export default function RequestLifecycleDemo() {
  const [step, setStep] = useState(0);
  const [revealed, setRevealed] = useState(false);
  const current = STAGES[step];

  const reveal = () => setRevealed(true);

  const next = () => {
    setStep((value) => Math.min(value + 1, STAGES.length - 1));
    setRevealed(false);
  };

  return (
    <div style={{ padding: 16, background: '#0d1117', color: '#e6edf3', fontFamily: 'sans-serif' }}>
      <p style={{ marginTop: 0, color: '#8b949e' }}>
        Predict the next stage before revealing it.
      </p>

      <div style={{
        display: 'flex',
        gap: 6,
        flexWrap: 'wrap',
        marginBottom: 16
      }}>
        {STAGES.map((stage, index) => (
          <div
            key={stage.name}
            style={{
              padding: '6px 10px',
              borderRadius: 6,
              background: index <= step ? '#238636' : '#161b22',
              border: '1px solid #30363d',
              fontSize: 12
            }}
          >
            {stage.name}
          </div>
        ))}
      </div>

      <div style={{
        padding: 16,
        background: '#161b22',
        borderRadius: 8,
        border: '1px solid #30363d',
        marginBottom: 12
      }}>
        <strong>{current.name}</strong>
        {revealed && (
          <p style={{ color: '#8b949e', marginBottom: 0 }}>
            {current.detail}
          </p>
        )}
      </div>

      <div style={{ display: 'flex', gap: 8 }}>
        <button onClick={reveal}>
          Reveal
        </button>
        <button onClick={next} disabled={step === STAGES.length - 1}>
          Next Stage
        </button>
      </div>
    </div>
  );
}

import React, { useState } from 'react';

const SCENARIOS = [
  {
    task: 'You want to experiment with a JavaScript solution.',
    answer: 'Playground',
    why: 'Playground is designed for code experiments, guided exercises, and feature building.'
  },
  {
    task: 'You are given broken code and need to find the cause.',
    answer: 'Debug Lab',
    why: 'Debug Lab is designed around reproducing, analyzing, and fixing bugs.'
  },
  {
    task: 'You need to plan a component tree before writing code.',
    answer: 'Whiteboard Mode',
    why: 'Whiteboard Mode is useful for planning structures, relationships, flows, and architecture.'
  },
  {
    task: 'You want to see whether your learning is improving over time.',
    answer: 'Grow',
    why: 'Grow is where Forge surfaces progress, mastery, readiness, and related learning evidence.'
  }
];

export default function ForgeToolDemo() {
  const [index, setIndex] = useState(0);
  const [revealed, setRevealed] = useState(false);
  const scenario = SCENARIOS[index];

  return (
    <div style={{ padding: 16, background: '#0d1117', color: '#e6edf3', fontFamily: 'sans-serif' }}>
      <p style={{ marginTop: 0, color: '#8b949e' }}>Choose the Forge surface you would use:</p>
      <div style={{ padding: 16, border: '1px solid #30363d', borderRadius: 8, marginBottom: 12 }}>
        <strong>{scenario.task}</strong>
      </div>
      {revealed && (
        <div style={{ padding: 12, background: '#161b22', borderRadius: 8, marginBottom: 12 }}>
          <p style={{ margin: '0 0 6px' }}>Best fit: <strong>{scenario.answer}</strong></p>
          <p style={{ margin: 0, color: '#8b949e' }}>{scenario.why}</p>
        </div>
      )}
      <div style={{ display: 'flex', gap: 8 }}>
        <button onClick={() => setRevealed(true)}>Reveal</button>
        <button
          onClick={() => {
            setIndex((value) => (value + 1) % SCENARIOS.length);
            setRevealed(false);
          }}
        >
          Next Scenario
        </button>
      </div>
    </div>
  );
}

