import React, { useState } from 'react';

export default function BoxModelLab() {
  const [boxSizing, setBoxSizing] = useState('content-box');
  const [padding, setPadding] = useState(20);
  const [border, setBorder] = useState(4);

  const width = 200;
  const outerWidth =
    boxSizing === 'border-box'
      ? width
      : width + padding * 2 + border * 2;

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
        <button onClick={() => setBoxSizing((value) => value === 'content-box' ? 'border-box' : 'content-box')}>
          box-sizing: {boxSizing}
        </button>
        <button onClick={() => setPadding((value) => value === 20 ? 40 : 20)}>
          Toggle padding: {padding}px
        </button>
        <button onClick={() => setBorder((value) => value === 4 ? 8 : 4)}>
          Toggle border: {border}px
        </button>
      </div>

      <div style={{
        width,
        padding,
        border: `${border}px solid #60a5fa`,
        boxSizing,
        background: '#161b22',
        borderRadius: 8
      }}>
        Content width: {width}px
      </div>

      <p style={{ color: '#8b949e', marginBottom: 0 }}>
        Predicted outer width: {outerWidth}px
      </p>
    </div>
  );
}

