import React, { useState } from 'react';

const directions = ['row', 'column'];
const justifications = ['flex-start', 'center', 'space-between'];
const alignments = ['stretch', 'flex-start', 'center', 'flex-end'];

export default function FlexboxLab() {
  const [direction, setDirection] = useState('row');
  const [justify, setJustify] = useState('space-between');
  const [align, setAlign] = useState('center');
  const [wrap, setWrap] = useState(false);

  return (
    <div style={{
      padding: 16,
      background: '#0d1117',
      color: '#e6edf3',
      fontFamily: 'system-ui, sans-serif'
    }}>
      <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 16 }}>
        <button onClick={() => setDirection((value) => value === 'row' ? 'column' : 'row')}>
          direction: {direction}
        </button>
        <button onClick={() => setJustify((value) => {
          const index = justifications.indexOf(value);
          return justifications[(index + 1) % justifications.length];
        })}>
          justify: {justify}
        </button>
        <button onClick={() => setAlign((value) => {
          const index = alignments.indexOf(value);
          return alignments[(index + 1) % alignments.length];
        })}>
          align: {align}
        </button>
        <button onClick={() => setWrap((value) => !value)}>
          wrap: {wrap ? 'on' : 'off'}
        </button>
      </div>

      <div style={{
        display: 'flex',
        flexDirection: direction,
        justifyContent: justify,
        alignItems: align,
        flexWrap: wrap ? 'wrap' : 'nowrap',
        gap: 12,
        minHeight: 220,
        padding: 16,
        border: '1px solid #30363d',
        borderRadius: 8,
        background: '#161b22'
      }}>
        {['HTML', 'CSS', 'JavaScript', 'React'].map((item) => (
          <div
            key={item}
            style={{
              padding: '14px 18px',
              background: '#2563eb',
              borderRadius: 8,
              whiteSpace: 'nowrap'
            }}
          >
            {item}
          </div>
        ))}
      </div>
    </div>
  );
}
